public int findShortest(int n, int[][] edges, int[] ids, int val) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    int best = Integer.MAX_VALUE;
    for (int start = 1; start <= n; start++) {
        if (ids[start - 1] != val) continue;
        int[] dist = new int[n + 1];
        Arrays.fill(dist, -1);
        Deque<Integer> queue = new ArrayDeque<>();
        queue.offer(start);
        dist[start] = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            if (u != start && ids[u - 1] == val) {
                best = Math.min(best, dist[u]);
                break;                       // nearest clone found from this start
            }
            for (int v : adj.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    queue.offer(v);
                }
            }
        }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
}

