from collections import deque

def find_shortest(self, n: int, edges: list[list[int]], ids: list[int], val: int) -> int:
    adj: list[list[int]] = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    best = float('inf')
    for start in range(1, n + 1):
        if ids[start - 1] != val:
            continue
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if u != start and ids[u - 1] == val:
                best = min(best, dist[u])
                break                        # nearest clone from this start
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
    return -1 if best == float('inf') else best

