public int findShortest(int n, int[][] edges, int[] ids, int val) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    int[] source = new int[n + 1];
    int[] dist = new int[n + 1];
    Arrays.fill(source, -1);
    Deque<Integer> queue = new ArrayDeque<>();
    for (int i = 1; i <= n; i++) {
        if (ids[i - 1] == val) {
            source[i] = i;                  // each clone is its own source
            dist[i] = 0;
            queue.offer(i);
        }
    }
    int best = Integer.MAX_VALUE;
    while (!queue.isEmpty()) {
        int u = queue.poll();
        for (int v : adj.get(u)) {
            if (source[v] == -1) {
                source[v] = source[u];
                dist[v] = dist[u] + 1;
                queue.offer(v);
            } else if (source[v] != source[u]) {   // two waves meet
                best = Math.min(best, dist[u] + dist[v] + 1);
            }
        }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
}

